describe('Active Filter Tags Above Search Results', () => {
  beforeEach(() => {
    cy.visit('/search');
  });

  it('should display a tag for each active filter above search results', () => {
    // Apply first filter
    cy.get('[data-testid="filter-category-all"]').click();
    cy.get('[data-testid="filter-category-electronics"]').click();
    cy.get('[data-testid="filter-price-range"]').click();
    cy.get('[data-testid="filter-price-range-0-100"]').click();

    // Verify filter tags are displayed
    cy.get('[data-testid="active-filter-tag"]').should('be.visible');
    cy.get('[data-testid="active-filter-tag"]').should('have.length', 2);

    // Verify first tag content
    cy.get('[data-testid="active-filter-tag"]').first().should('contain', 'Category: Electronics');
    cy.get('[data-testid="active-filter-tag"]').first().should('have.class', 'active-filter-tag');

    // Verify second tag content
    cy.get('[data-testid="active-filter-tag"]').eq(1).should('contain', 'Price Range: $0 - $100');
    cy.get('[data-testid="active-filter-tag"]').eq(1).should('have.class', 'active-filter-tag');

    // Verify results are displayed
    cy.get('[data-testid="search-results-list"]').should('be.visible');
    cy.get('[data-testid="search-results-item"]').should('have.length.greaterThan', 0);

    // Verify each tag has a remove button
    cy.get('[data-testid="active-filter-tag"]').each(($tag) => {
      cy.wrap($tag).find('[data-testid="remove-filter-btn"]').should('be.visible');
    });
  });

  it('should remove a filter tag when the remove button is clicked', () => {
    // Apply multiple filters
    cy.get('[data-testid="filter-category-all"]').click();
    cy.get('[data-testid="filter-category-electronics"]').click();
    cy.get('[data-testid="filter-price-range"]').click();
    cy.get('[data-testid="filter-price-range-0-100"]').click();
    cy.get('[data-testid="filter-brand-sony"]').click();

    // Verify all tags are visible
    cy.get('[data-testid="active-filter-tag"]').should('have.length', 3);

    // Click remove button on the first tag (Category)
    cy.get('[data-testid="active-filter-tag"]').first().find('[data-testid="remove-filter-btn"]').click();

    // Verify the first tag is removed
    cy.get('[data-testid="active-filter-tag"]').should('have.length', 2);

    // Verify the remaining tags are still visible
    cy.get('[data-testid="active-filter-tag"]').should('contain', 'Price Range: $0 - $100');
    cy.get('[data-testid="active-filter-tag"]').should('contain', 'Brand: Sony');

    // Verify results are updated after filter removal
    cy.get('[data-testid="search-results-list"]').should('be.visible');
    cy.get('[data-testid="search-results-item"]').should('have.length.greaterThan', 0);

    // Verify the removed filter is no longer applied
    cy.get('[data-testid="filter-category-all"]').should('be.visible');
  });
});
